const fs = require('fs');

function dkdRead(dkdFile) { return fs.readFileSync(dkdFile, 'utf8'); }
function dkdWrite(dkdFile, dkdValue) { fs.writeFileSync(dkdFile, dkdValue); }
function dkdReplace(dkdFile, dkdOld, dkdNext, dkdLabel) {
  let dkdSource = dkdRead(dkdFile);
  if (dkdSource.includes(dkdNext)) return;
  if (!dkdSource.includes(dkdOld)) throw new Error(`Missing ${dkdLabel} in ${dkdFile}`);
  dkdSource = dkdSource.replace(dkdOld, dkdNext);
  dkdWrite(dkdFile, dkdSource);
}
function dkdReplaceAll(dkdFile, dkdOld, dkdNext, dkdLabel) {
  let dkdSource = dkdRead(dkdFile);
  if (!dkdSource.includes(dkdOld)) {
    if (dkdSource.includes(dkdNext)) return;
    throw new Error(`Missing ${dkdLabel} in ${dkdFile}`);
  }
  dkdSource = dkdSource.split(dkdOld).join(dkdNext);
  dkdWrite(dkdFile, dkdSource);
}

